const fs = require('fs');
const path = require('path');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  const htmlPath = path.resolve('index.html');
  const htmlContent = fs.readFileSync(htmlPath, 'utf8');

  // Inject CSS for proper layout testing
  const cssPath = path.resolve('style.css');
  const cssContent = fs.readFileSync(cssPath, 'utf8');

  await page.setContent(htmlContent, { waitUntil: 'load' });
  await page.addStyleTag({ content: cssContent });

  // Inject script to ensure dynamic states are evaluated
  const scriptPath = path.resolve('script.js');
  const scriptContent = fs.readFileSync(scriptPath, 'utf8');
  await page.addScriptTag({ content: scriptContent });

  // Load axe-core
  const axePath = require.resolve('axe-core/axe.min.js');
  await page.addScriptTag({ path: axePath });

  const results = await page.evaluate(async () => {
    return await window.axe.run();
  });

  const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
  const bp = results.violations.filter(v => v.tags.includes('best-practice'));

  console.log(JSON.stringify({
    wcag: wcag.map(v => ({ id: v.id, impact: v.impact, help: v.help, nodes: v.nodes.map(n => n.target) })),
    bp: bp.map(v => ({ id: v.id, impact: v.impact, help: v.help, nodes: v.nodes.map(n => n.target) }))
  }, null, 2));

  await browser.close();
  process.exit(wcag.length > 0 ? 1 : 0);
})();
