     <main id="main-content">
         <form id="quiz-form" novalidate>
             <div class="form-field">
                 <fieldset aria-describedby="q1-help">
                     <legend>Which of these are statically typed languages? <span aria-hidden="true">*</span></legend>
                     <p id="q1-help" class="help-text">Statically typed languages check types at compile-time.</p>

                     <div class="option">
                         <input type="checkbox" id="q1-o1" name="q1" value="java">
                         <label for="q1-o1">Java</label>
                     </div>
                     <div class="option">
                         <input type="checkbox" id="q1-o2" name="q1" value="python">
                         <label for="q1-o2">Python</label>
                     </div>
                     <div class="option">
                         <input type="checkbox" id="q1-o3" name="q1" value="cpp">
                         <label for="q1-o3">C++</label>
                     </div>
                     <div class="option">
                         <input type="checkbox" id="q1-o4" name="q1" value="ruby">
                         <label for="q1-o4">Ruby</label>
                     </div>
                 </fieldset>
             </div>

             <div class="form-field">
                 <fieldset>
                     <legend>Which languages are commonly used for web development? <span aria-hidden="true">*</span></legend>

                     <div class="option">
                         <input type="checkbox" id="q2-o1" name="q2" value="javascript">
                         <label for="q2-o1">JavaScript</label>
                     </div>
                     <div class="option">
                         <input type="checkbox" id="q2-o2" name="q2" value="php">
                         <label for="q2-o2">PHP</label>
                     </div>
                     <div class="option">
                         <input type="checkbox" id="q2-o3" name="q2" value="python">
                         <label for="q2-o3">Python</label>
                     </div>
                     <div class="option">
                         <input type="checkbox" id="q2-o4" name="q2" value="c">
                         <label for="q2-o4">C</label>
                     </div>
                 </fieldset>
             </div>

             <div class="form-field">
                 <fieldset>
                     <legend>Which of these are compiled languages? <span aria-hidden="true">*</span></legend>

                     <div class="option">
                         <input type="checkbox" id="q3-o1" name="q3" value="c">
                         <label for="q3-o1">C</label>
                     </div>
                     <div class="option">
                         <input type="checkbox" id="q3-o2" name="q3" value="go">
                         <label for="q3-o2">Go</label>
                     </div>
                     <div class="option">
                         <input type="checkbox" id="q3-o3" name="q3" value="javascript">
                         <label for="q3-o3">JavaScript</label>
                     </div>
                     <div class="option">
                         <input type="checkbox" id="q3-o4" name="q3" value="python">
                         <label for="q3-o4">Python</label>
                     </div>
