     <script>
         document.addEventListener('DOMContentLoaded', () => {
             const quizForm = document.getElementById('quiz-form');
             const resultsDiv = document.getElementById('results');

             const correctAnswers = {
                 q1: ['java', 'cpp'],
                 q2: ['javascript', 'php', 'python'],
                 q3: ['c', 'go']
             };

             quizForm.addEventListener('submit', (e) => {
                 e.preventDefault();

                 const formData = new FormData(quizForm);
                 let score = 0;
                 const totalQuestions = Object.keys(correctAnswers).length;

                 // Reset previous results
                 resultsDiv.innerHTML = '';
                 resultsDiv.className = '';

                 Object.keys(correctAnswers).forEach(qKey => {
                     const selected = formData.getAll(qKey);
                     const correct = correctAnswers[qKey];

                     // Check if selected matches correct exactly
                     const isCorrect = selected.length === correct.length && 
                                       selected.every(val => correct.includes(val));

                     if (isCorrect) {
                         score++;
                     }
                 });

                 // Display results
                 const scoreText = `You scored ${score} out of ${totalQuestions}!`;
                 const resultMessage = document.createElement('p');
                 resultMessage.textContent = scoreText;
                 resultMessage.style.fontWeight = 'bold';
                 resultMessage.style.fontSize = '1.25rem';

                 resultsDiv.appendChild(resultMessage);

                 if (score === totalQuestions) {
                     resultsDiv.classList.add('result-success');
                     const subText = document.createElement('p');
                     subText.textContent = "Perfect! You're a language expert.";
                     resultsDiv.appendChild(subText);
                 } else {
                     resultsDiv.classList.add('result-error');
                     const subText = document.createElement('p');
                     subText.textContent = "Keep learning and try again!";
                     resultsDiv.appendChild(subText);
                 }

                 // Move focus to results for accessibility
                 resultsDiv.setAttribute('tabindex', '-1');
                 resultsDiv.focus();
             });
         });
     </script>
